import {Router} from "express";
import crypto from "crypto";
import {z} from "zod";
import {prisma} from "../prisma.js";
import {auth} from "../middleware/auth.js";
import {buildSaleFingerprint,findRecentSimilarSale,findSaleByClientTransaction,insertPosSaleSafetyAudit} from "../pos-sale-safety.js";
import {sendEmail} from "../services/mail.js";

const router=Router();
router.use(auth);
let holdTablesReady=false;
let audienceDiscountTableReady=false;
let audienceSelectionTableReady=false;
let audienceCardTableReady=false;
let loyaltyTableReady=false;
let saleOperationChannelReady=false;
const META_SEP="::MWSMETA::";

function assertStore(req,storeId){if(req.user?.tokenType==="STORE_OPERATOR"&&req.user.storeId!==storeId){const error=new Error("Η πρόσβαση ισχύει μόνο για το δικό σου κατάστημα.");error.status=403;throw error}}
async function storeFor(req,storeId){const row=await prisma.store.findFirst({where:{id:storeId,companyId:req.user.companyId,active:true},select:{id:true,name:true,companyId:true}});if(!row){const error=new Error("Δεν βρέθηκε ενεργό κατάστημα.");error.status=404;throw error}return row}
async function hasTableService(companyId,storeId){try{const rows=await prisma.$queryRaw`SELECT EXISTS(SELECT 1 FROM "CompanyModule" cm JOIN "StoreTableServiceConfig" cfg ON cfg."companyId"=cm."companyId" WHERE cm."companyId"=${companyId} AND cm."moduleKey"='TABLE_SERVICE' AND cm."active"=TRUE AND cfg."storeId"=${storeId} AND cfg."enabled"=TRUE) AS enabled`;return Boolean(rows[0]?.enabled)}catch{return false}}
async function requestTerminal(req){
  const testTerminal=(process.env.CI==="true"||process.env.NODE_ENV==="test"||process.env.MWS_E2E_TERMINAL_OVERRIDE==="1")?String(req.query?.mwsTerminal||req.headers?.["x-mws-terminal-pos"]||req.body?.terminalPos||"").trim():"";
  if(testTerminal)return testTerminal.toUpperCase().slice(0,120);
  if(req.user?.tokenType==="STORE_OPERATOR"){
    const liveTerminal=String(req.user?.terminalPos||"").trim();
    if(liveTerminal)return liveTerminal.toUpperCase().slice(0,120);
    const rows=await prisma.$queryRaw`SELECT COALESCE(NULLIF(TRIM(p."terminalPos"),''),'MAIN') AS "terminalPos" FROM "StoreOperatorProfile" p WHERE p."companyId"=${req.user.companyId} AND p."storeId"=${req.user.storeId} AND p."employeeId"=${req.user.employeeId} LIMIT 1`;
    return String(rows[0]?.terminalPos||rows[0]?.terminalpos||"MAIN").trim().toUpperCase().slice(0,120)||"MAIN";
  }
  return String(req.headers?.["x-mws-terminal-pos"]||"MAIN").trim().toUpperCase().slice(0,120)||"MAIN";
}
const money=v=>Number(v||0);const round2=v=>Number(Number(v||0).toFixed(2));
const removeCodesFromStored=(value,remove)=>{const raw=String(value||""),parts=raw.split(META_SEP),base=parts[0],meta=parts.slice(1).join(META_SEP);if(!meta)return raw;const codes=meta.split(",").filter(Boolean).map(code=>{try{return decodeURIComponent(code)}catch{return code}}).filter(code=>!remove.has(code));return codes.length?`${base}${META_SEP}${codes.map(code=>encodeURIComponent(String(code))).join(",")}`:base};
async function ensureHoldTable(){if(holdTablesReady)return;await prisma.$executeRawUnsafe(`CREATE TABLE IF NOT EXISTS "PosHeldTransaction" ("id" TEXT PRIMARY KEY,"companyId" TEXT NOT NULL,"storeId" TEXT NOT NULL,"sessionId" TEXT,"operatorId" TEXT NOT NULL,"operatorName" TEXT,"customerId" TEXT,"customerName" TEXT,"itemsJson" JSONB NOT NULL DEFAULT '[]'::jsonb,"total" NUMERIC(14,2) NOT NULL DEFAULT 0,"status" TEXT NOT NULL DEFAULT 'HELD',"heldAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),"restoredAt" TIMESTAMPTZ,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW())`);await prisma.$executeRawUnsafe(`ALTER TABLE "PosHeldTransaction" ADD COLUMN IF NOT EXISTS "customerId" TEXT`);await prisma.$executeRawUnsafe(`ALTER TABLE "PosHeldTransaction" ADD COLUMN IF NOT EXISTS "customerName" TEXT`);await prisma.$executeRawUnsafe(`CREATE INDEX IF NOT EXISTS "PosHeldTransaction_store_status_idx" ON "PosHeldTransaction" ("storeId","status","heldAt" DESC)`);holdTablesReady=true}
async function ensureAudienceDiscountTable(){if(audienceDiscountTableReady)return;await prisma.$executeRawUnsafe(`CREATE TABLE IF NOT EXISTS "StoreProductAudienceDiscount" ("id" TEXT PRIMARY KEY,"companyId" TEXT NOT NULL,"storeId" TEXT NOT NULL,"productId" TEXT NOT NULL,"audience" TEXT NOT NULL,"discountPercent" NUMERIC(6,2) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT TRUE,"createdByUserId" TEXT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE("storeId","productId","audience"),CHECK ("audience" IN ('DOCTOR','NURSE','STAFF','CUSTOMER')),CHECK ("discountPercent">=0 AND "discountPercent"<=100))`);audienceDiscountTableReady=true}
async function ensureAudienceSelectionTable(){if(audienceSelectionTableReady)return;await prisma.$executeRawUnsafe(`CREATE TABLE IF NOT EXISTS "PosAudienceSelection" ("companyId" TEXT NOT NULL,"storeId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"audience" TEXT NOT NULL DEFAULT 'NORMAL',"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY("companyId","storeId","actorId"),CHECK ("audience" IN ('NORMAL','DOCTOR','NURSE','STAFF','CUSTOMER')))`);audienceSelectionTableReady=true}
async function ensureAudienceCardTable(){if(audienceCardTableReady)return;await prisma.$executeRawUnsafe(`CREATE TABLE IF NOT EXISTS "AudienceDiscountCard" ("id" TEXT PRIMARY KEY,"companyId" TEXT NOT NULL,"storeId" TEXT NOT NULL,"cardHash" TEXT NOT NULL,"cardLast4" TEXT NOT NULL,"label" TEXT NOT NULL,"audience" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT TRUE,"createdByUserId" TEXT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE("companyId","storeId","cardHash"),CHECK ("audience" IN ('DOCTOR','NURSE','STAFF','CUSTOMER')))`);audienceCardTableReady=true}
async function ensureLoyaltyTable(){if(loyaltyTableReady)return;await prisma.$executeRawUnsafe(`CREATE TABLE IF NOT EXISTS "CustomerLoyaltyLedger" ("id" TEXT PRIMARY KEY,"companyId" TEXT NOT NULL,"storeId" TEXT NOT NULL,"customerId" TEXT NOT NULL,"saleId" TEXT,"sessionId" TEXT,"type" TEXT NOT NULL,"points" NUMERIC(14,2) NOT NULL,"amount" NUMERIC(14,2),"actorId" TEXT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK ("type" IN ('EARN','REDEEM','ADJUSTMENT')))`);await prisma.$executeRawUnsafe(`CREATE INDEX IF NOT EXISTS "CustomerLoyaltyLedger_customer_idx" ON "CustomerLoyaltyLedger" ("companyId","customerId","createdAt" DESC)`);loyaltyTableReady=true}
async function ensureSaleOperationChannel(){if(saleOperationChannelReady)return;await prisma.$executeRawUnsafe(`ALTER TABLE "Sale" ADD COLUMN IF NOT EXISTS "operationChannel" TEXT NOT NULL DEFAULT 'COUNTER'`);await prisma.$executeRawUnsafe(`CREATE INDEX IF NOT EXISTS "Sale_store_operationChannel_idx" ON "Sale" ("storeId","operationChannel","occurredAt" DESC)`);saleOperationChannelReady=true}
const normalizeAudienceCard=value=>String(value||"").trim().toUpperCase().replace(/[^A-Z0-9]/g,"");
const audienceCardHash=value=>crypto.createHash("sha256").update(normalizeAudienceCard(value)).digest("hex");
async function saveAudienceSelection(req,storeId,audience){await ensureAudienceSelectionTable();await prisma.$executeRaw`INSERT INTO "PosAudienceSelection" ("companyId","storeId","actorId","audience") VALUES (${req.user.companyId},${storeId},${req.user.id},${audience}) ON CONFLICT ("companyId","storeId","actorId") DO UPDATE SET "audience"=EXCLUDED."audience","updatedAt"=NOW()`}
async function currentAudience(req,storeId){await ensureAudienceSelectionTable();const rows=await prisma.$queryRaw`SELECT "audience" FROM "PosAudienceSelection" WHERE "companyId"=${req.user.companyId} AND "storeId"=${storeId} AND "actorId"=${req.user.id} LIMIT 1`;return rows[0]?.audience||"NORMAL"}
async function notifyCustomerBalance(customer,{kind,amount,balance}){if(!customer?.email)return {status:"SKIPPED",reason:"NO_EMAIL"};try{await sendEmail({to:[customer.email],subject:`MyWorkStation · Ενημέρωση υπολοίπου ${customer.name}`,text:`${kind}\nΠοσό: ${money(amount).toFixed(2)} €\nΝέο υπόλοιπο: ${money(balance).toFixed(2)} €`,html:`<div style="font-family:Arial,sans-serif"><h2>Ενημέρωση υπολοίπου</h2><p>${kind}</p><p><b>Ποσό:</b> ${money(amount).toFixed(2)} €</p><p><b>Νέο υπόλοιπο:</b> ${money(balance).toFixed(2)} €</p></div>`});return {status:"SENT"}}catch(error){console.error("Customer balance email failed",error?.message||error);return {status:"FAILED"}}}
async function applyAudienceDiscounts(req,store,items,audience){if(!["DOCTOR","NURSE","STAFF","CUSTOMER"].includes(audience))return items;await ensureAudienceDiscountTable();const ids=items.map(item=>item.productId),rows=await prisma.$queryRaw`SELECT "productId","discountPercent" FROM "StoreProductAudienceDiscount" WHERE "companyId"=${req.user.companyId} AND "storeId"=${store.id} AND "audience"=${audience} AND "active"=true AND "productId"=ANY(${ids}::text[])`,byId=new Map(rows.map(row=>[row.productId,money(row.discountPercent)]));for(const item of items){const percent=byId.get(item.productId);if(!(percent>0))continue;const before=money(item.lineTotal),after=Math.ceil((before*(1-percent/100)-Number.EPSILON)*10)/10;item.discount=round2(money(item.discount)+(before-after));item.lineTotal=after;item.effectiveUnitPrice=item.quantity?round2(after/item.quantity):item.effectiveUnitPrice;item.price=item.effectiveUnitPrice;item.priceSource=`AUDIENCE_${audience}`;item.audience=audience;item.audienceDiscountPercent=percent}return items}

async function resolveCustomer(req,customerId){if(!customerId)return null;const rows=await prisma.$queryRaw`SELECT "id","name","taxId","phone","email","discountPercent","creditLimit","balance","points","memberCard" FROM "Customer" WHERE "id"=${customerId} AND "companyId"=${req.user.companyId} AND "active"=true LIMIT 1`;const customer=rows[0];if(!customer){const error=new Error("Ο πελάτης δεν βρέθηκε ή δεν είναι ενεργός στην εταιρεία.");error.status=400;throw error}return {...customer,discountPercent:money(customer.discountPercent),creditLimit:money(customer.creditLimit),balance:money(customer.balance),points:money(customer.points),hasMemberCard:Boolean(String(customer.memberCard||"").trim())}}
async function promotionSettings(companyId){try{const rows=await prisma.$queryRaw`SELECT "settings" FROM "ManagementParameters" WHERE "companyId"=${companyId} LIMIT 1`;return {leafletOnlyWithCustomerCard:Boolean(rows[0]?.settings?.backoffice?.leafletOnlyWithCustomerCard)}}catch{return {leafletOnlyWithCustomerCard:false}}}

router.get("/stores/:storeId",async(req,res,next)=>{try{assertStore(req,req.params.storeId);const store=await storeFor(req,req.params.storeId);const [layoutRows,tableServiceEnabled]=await Promise.all([prisma.$queryRawUnsafe(`SELECT "layoutJson","version","publishedAt" FROM "StorePosLayout" WHERE "storeId"=$1 LIMIT 1`,store.id).catch(()=>[]),hasTableService(req.user.companyId,store.id)]);const products=await prisma.$queryRaw`SELECT p."id",p."sku",p."name",p."vatRate",COALESCE(sp."salePrice",p."salePrice") AS "salePrice",COALESCE(sp."currentStock",0) AS "currentStock",c."name" AS "categoryName",COALESCE((SELECT json_agg(pb."barcode" ORDER BY pb."barcode") FROM "ProductBarcode" pb WHERE pb."productId"=p."id"),'[]') AS "barcodes" FROM "StoreProduct" sp JOIN "Product" p ON p."id"=sp."productId" AND p."companyId"=${req.user.companyId} LEFT JOIN "ProductCategory" c ON c."id"=p."categoryId" WHERE sp."storeId"=${store.id} AND sp."active"=true AND p."active"=true ORDER BY c."name" NULLS LAST,p."name" LIMIT 5000`;res.json({store,tableServiceEnabled,layout:layoutRows[0]?.layoutJson||null,layoutVersion:Number(layoutRows[0]?.version||0),publishedAt:layoutRows[0]?.publishedAt||null,products:products.map(row=>({...row,salePrice:money(row.salePrice),currentStock:money(row.currentStock),vatRate:money(row.vatRate)}))})}catch(error){next(error)}});
const layoutRemoveSchema=z.object({codes:z.array(z.string().min(1)).min(1).max(100)});
router.delete("/stores/:storeId/layout/categories/:buttonId/products",async(req,res,next)=>{try{assertStore(req,req.params.storeId);if(req.user?.tokenType==="STORE_OPERATOR"&&req.user?.role!=="MANAGER")return res.status(403).json({error:"Μόνο ο Υπεύθυνος μπορεί να αφαιρεί προϊόντα από κατηγορίες POS."});const store=await storeFor(req,req.params.storeId),body=layoutRemoveSchema.parse(req.body||{}),remove=new Set(body.codes.map(code=>String(code)));const rows=await prisma.$queryRawUnsafe(`SELECT "layoutJson","version" FROM "StorePosLayout" WHERE "storeId"=$1 LIMIT 1`,store.id);if(!rows[0])return res.status(404).json({error:"Δεν υπάρχει δημοσιευμένη διάταξη POS για το κατάστημα."});const layout=rows[0].layoutJson&&typeof rows[0].layoutJson==="object"?structuredClone(rows[0].layoutJson):null;if(!layout)return res.status(400).json({error:"Η δημοσιευμένη διάταξη POS δεν είναι έγκυρη."});let found=false;for(const listName of ["categories","quickKeys"]){const list=Array.isArray(layout[listName])?layout[listName]:[];const target=list.find(button=>String(button?.id||"")===String(req.params.buttonId));if(!target)continue;found=true;if(Array.isArray(target.productCodes))target.productCodes=target.productCodes.filter(code=>!remove.has(String(code)));const field=listName==="categories"?"categoryName":"productQuery";target[field]=removeCodesFromStored(target[field],remove)}if(!found)return res.status(404).json({error:"Η κατηγορία POS δεν βρέθηκε στη δημοσιευμένη διάταξη."});const updated=await prisma.$queryRawUnsafe(`UPDATE "StorePosLayout" SET "layoutJson"=$2::jsonb,"version"="version"+1,"publishedAt"=NOW() WHERE "storeId"=$1 RETURNING "version"`,store.id,JSON.stringify(layout));res.json({ok:true,layout,version:Number(updated[0]?.version||Number(rows[0].version||0)+1)})}catch(error){if(error?.name==="ZodError")return res.status(400).json({error:"Η αφαίρεση προϊόντος από κατηγορία δεν είναι έγκυρη.",details:error.issues});next(error)}});
router.get("/stores/:storeId/customers",async(req,res,next)=>{try{assertStore(req,req.params.storeId);await storeFor(req,req.params.storeId);const q=String(req.query.q||"").trim();if(q.length<2)return res.json({items:[]});const like=`%${q}%`;const rows=await prisma.$queryRaw`SELECT "id","name","taxId","phone","email","discountPercent","creditLimit","balance","points","memberCard" FROM "Customer" WHERE "companyId"=${req.user.companyId} AND "active"=true AND ("name" ILIKE ${like} OR COALESCE("taxId",'') ILIKE ${like} OR COALESCE("phone",'') ILIKE ${like} OR COALESCE("email",'') ILIKE ${like} OR COALESCE("memberCard",'') ILIKE ${like}) ORDER BY "name" LIMIT 30`;res.json({items:rows.map(row=>({...row,discountPercent:money(row.discountPercent),creditLimit:money(row.creditLimit),balance:money(row.balance),points:money(row.points),hasMemberCard:Boolean(String(row.memberCard||"").trim()),memberCard:undefined}))})}catch(error){next(error)}});
router.get("/stores/:storeId/audience-discounts",async(req,res,next)=>{try{assertStore(req,req.params.storeId);const store=await storeFor(req,req.params.storeId);await ensureAudienceDiscountTable();const rows=await prisma.$queryRaw`SELECT "productId","audience","discountPercent" FROM "StoreProductAudienceDiscount" WHERE "companyId"=${req.user.companyId} AND "storeId"=${store.id} AND "active"=true ORDER BY "audience","productId"`;res.json({items:rows.map(row=>({...row,discountPercent:money(row.discountPercent)}))})}catch(error){next(error)}});
router.post("/stores/:storeId/audience-selection",async(req,res,next)=>{try{assertStore(req,req.params.storeId);const store=await storeFor(req,req.params.storeId),audience=z.enum(["NORMAL","DOCTOR","NURSE","STAFF","CUSTOMER"]).parse(req.body?.audience);await ensureAudienceSelectionTable();await prisma.$executeRaw`INSERT INTO "PosAudienceSelection" ("companyId","storeId","actorId","audience") VALUES (${req.user.companyId},${store.id},${req.user.id},${audience}) ON CONFLICT ("companyId","storeId","actorId") DO UPDATE SET "audience"=EXCLUDED."audience","updatedAt"=NOW()`;res.json({ok:true,audience})}catch(error){next(error)}});
router.post("/stores/:storeId/audience-card/scan",async(req,res,next)=>{try{assertStore(req,req.params.storeId);const store=await storeFor(req,req.params.storeId),cardCode=z.string().trim().min(3).max(120).parse(req.body?.cardCode),normalized=normalizeAudienceCard(cardCode);if(normalized.length<3)return res.status(400).json({error:"Η κάρτα δεν είναι έγκυρη."});const hash=audienceCardHash(normalized);await ensureAudienceCardTable();let rows=await prisma.$queryRaw`SELECT "audience","label","cardLast4" FROM "AudienceDiscountCard" WHERE "companyId"=${req.user.companyId} AND "storeId"=${store.id} AND "cardHash"=${hash} AND "active"=true LIMIT 1`;let match=rows[0],customer=null;if(!match){rows=await prisma.$queryRaw`SELECT e."fullName" AS "label" FROM "StoreOperatorCredential" c JOIN "Employee" e ON e."id"=c."employeeId" WHERE c."companyId"=${req.user.companyId} AND c."storeId"=${store.id} AND c."cardCodeHash"=${hash} AND c."active"=true LIMIT 1`;if(rows[0])match={audience:"STAFF",label:rows[0].label,cardLast4:normalized.slice(-4)}}if(!match){rows=await prisma.$queryRaw`SELECT "id","name","balance","creditLimit","points" FROM "Customer" WHERE "companyId"=${req.user.companyId} AND "active"=true AND UPPER(REGEXP_REPLACE(COALESCE("memberCard",''),'[^A-Za-z0-9]','','g'))=${normalized} LIMIT 1`;if(rows[0]){customer={id:rows[0].id,name:rows[0].name,balance:money(rows[0].balance),creditLimit:money(rows[0].creditLimit),points:money(rows[0].points)};match={audience:"CUSTOMER",label:rows[0].name,cardLast4:normalized.slice(-4)}}}if(!match)return res.status(404).json({error:"Η κάρτα δεν είναι καταχωρημένη ως δικαιούχος έκπτωσης."});await saveAudienceSelection(req,store.id,match.audience);await prisma.$executeRaw`INSERT INTO "StoreOperatorAudit" ("id","companyId","storeId","operatorId","actorId","eventType","details") VALUES (${crypto.randomUUID()},${req.user.companyId},${store.id},${req.user.operatorId||req.user.id},${req.user.id},'AUDIENCE_CARD_SCANNED',${JSON.stringify({audience:match.audience,label:match.label,cardLast4:match.cardLast4})}::jsonb)`;res.json({ok:true,audience:match.audience,label:match.label,cardLast4:match.cardLast4,customer})}catch(error){next(error)}});
router.post("/stores/:storeId/customer-balance-payment",async(req,res,next)=>{try{assertStore(req,req.params.storeId);const store=await storeFor(req,req.params.storeId),terminalPos=await requestTerminal(req),body=z.object({customerId:z.string().min(1),amount:z.coerce.number().positive().max(999999999),method:z.enum(["CASH","CARD"])}).parse(req.body||{}),actorName=req.user.fullName||"Πωλητής",ledgerId=crypto.randomUUID(),earnedPoints=Math.floor(body.amount);await ensureLoyaltyTable();const result=await prisma.$transaction(async tx=>{const customer=(await tx.$queryRaw`SELECT "id","name","email","balance","points" FROM "Customer" WHERE "id"=${body.customerId} AND "companyId"=${req.user.companyId} AND "active"=true FOR UPDATE`)[0];if(!customer){const error=new Error("Ο πελάτης δεν βρέθηκε.");error.status=404;throw error}const previousBalance=money(customer.balance);if(previousBalance<=0){const error=new Error("Ο πελάτης δεν έχει χρεωστικό υπόλοιπο.");error.status=409;throw error}if(body.amount-previousBalance>.009){const error=new Error(`Η πληρωμή δεν μπορεί να υπερβαίνει το υπόλοιπο ${previousBalance.toFixed(2)} €.`);error.status=409;throw error}const shift=(await tx.$queryRaw`SELECT "id" FROM "CashShiftSession" WHERE "companyId"=${req.user.companyId} AND "storeId"=${store.id} AND "terminalPos"=${terminalPos} AND "status"='OPEN' ORDER BY "openedAt" DESC LIMIT 1 FOR KEY SHARE`)[0];if(!shift){const error=new Error(`Δεν υπάρχει ανοιχτή βάρδια στο ${terminalPos}.`);error.status=409;throw error}const balance=round2(previousBalance-body.amount),points=money(customer.points)+earnedPoints;await tx.$executeRaw`UPDATE "Customer" SET "balance"=${balance},"points"=${points},"updatedAt"=NOW() WHERE "id"=${customer.id} AND "companyId"=${req.user.companyId}`;await tx.$executeRaw`INSERT INTO "CustomerLedger" ("id","customerId","storeId","entryType","amount","referenceType","referenceId","note","actorId","actorName","paymentMethod","sessionId") VALUES (${ledgerId},${customer.id},${store.id},'RECEIPT',${-body.amount},'POS_CUSTOMER_RECEIPT',${ledgerId},${`Πληρωμή υπολοίπου POS · ${body.method}`},${req.user.id},${actorName},${body.method},${shift.id})`;if(earnedPoints>0)await tx.$executeRaw`INSERT INTO "CustomerLoyaltyLedger" ("id","companyId","storeId","customerId","sessionId","type","points","amount","actorId") VALUES (${crypto.randomUUID()},${req.user.companyId},${store.id},${customer.id},${shift.id},'EARN',${earnedPoints},${body.amount},${req.user.id})`;await tx.$executeRaw`INSERT INTO "StoreTransaction" ("id","companyId","storeId","sessionId","type","amount","description","actorId","actorName") VALUES (${crypto.randomUUID()},${req.user.companyId},${store.id},${shift.id},${body.method==="CASH"?"CUSTOMER_RECEIPT_CASH":"CUSTOMER_RECEIPT_CARD"},${body.amount},${`Είσπραξη πελάτη ${customer.name} · ${ledgerId}`},${req.user.id},${actorName})`;await tx.$executeRaw`INSERT INTO "StoreOperatorAudit" ("id","companyId","storeId","operatorId","actorId","eventType","details") VALUES (${crypto.randomUUID()},${req.user.companyId},${store.id},${req.user.operatorId||req.user.id},${req.user.id},'CUSTOMER_BALANCE_PAYMENT',${JSON.stringify({customerId:customer.id,ledgerId,amount:body.amount,method:body.method,previousBalance,balance,earnedPoints,sessionId:shift.id})}::jsonb)`;return {customer:{id:customer.id,name:customer.name,email:customer.email},previousBalance,balance,points}});const emailNotification=await notifyCustomerBalance(result.customer,{kind:`Πληρωμή υπολοίπου με ${body.method==="CASH"?"μετρητά":"κάρτα"}`,amount:body.amount,balance:result.balance});res.status(201).json({ok:true,ledgerId,amount:body.amount,method:body.method,earnedPoints,...result,emailNotification})}catch(error){next(error)}});
router.get("/stores/:storeId/customers/:customerId/prices",async(req,res,next)=>{try{assertStore(req,req.params.storeId);const store=await storeFor(req,req.params.storeId),customer=await resolveCustomer(req,req.params.customerId);const rows=await prisma.$queryRaw`SELECT w."productId",w."wholesalePrice" FROM "CustomerWholesalePrice" w JOIN "Product" p ON p."id"=w."productId" AND p."companyId"=w."companyId" AND p."active"=true JOIN "StoreProduct" sp ON sp."productId"=p."id" AND sp."storeId"=${store.id} AND sp."active"=true WHERE w."companyId"=${req.user.companyId} AND w."customerId"=${customer.id} AND w."active"=true ORDER BY w."productId"`;res.json({customerId:customer.id,items:rows.map(row=>({productId:row.productId,wholesalePrice:money(row.wholesalePrice)}))})}catch(error){next(error)}});

const cartItemSchema=z.object({productId:z.string().min(1),quantity:z.coerce.number().positive().max(999)});
const checkoutItemSchema=cartItemSchema.extend({unitPriceOverride:z.coerce.number().min(0).max(999999).optional().nullable(),overrideReason:z.string().trim().max(300).optional().nullable()}).superRefine((value,ctx)=>{if(value.unitPriceOverride!==undefined&&value.unitPriceOverride!==null&&!String(value.overrideReason||"").trim())ctx.addIssue({code:z.ZodIssueCode.custom,path:["overrideReason"],message:"Η χειροκίνητη αλλαγή τιμής απαιτεί αιτιολογία."})});
const audienceSchema=z.enum(["NORMAL","DOCTOR","NURSE","STAFF","CUSTOMER"]);
const quoteSchema=z.object({items:z.array(cartItemSchema).min(1).max(200),customerId:z.string().min(1).optional().nullable(),audience:audienceSchema.optional().default("NORMAL")});
const paymentMethodSchema=z.enum(["CASH","CARD","IRIS","CREDIT"]);
